package vn.svframe.svframelib.api.crafting.recipes; import vn.svframe.svframelib.api.crafting.ingredients.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; public class SVFrameCachedResult { public static final String cacheNBTTagPath="SVFRAMELIB_CRAFTING_CACHE"; private static final Map<UUID,SVFrameCachedResult> CACHE=new ConcurrentHashMap<>(); private final UUID id; private final SVFrameBlueprintInventory result; private final SVFrameRecipeBlueprint operation; private final SVFrameRecipeInventory display; private int times; public SVFrameCachedResult(UUID id,SVFrameBlueprintInventory result,SVFrameRecipeBlueprint op,SVFrameRecipeInventory display,int times){this.id=id;this.result=result;operation=op;this.display=display;this.times=times;CACHE.put(id,this);} public void unload(){CACHE.remove(id);} public UUID getOperationIdentifier(){return id;} public SVFrameBlueprintInventory getResultOfOperation(){return result;} public SVFrameRecipeBlueprint getOperation(){return operation;} public static SVFrameCachedResult get(UUID id){return CACHE.get(id);} public int getTimes(){return times;} public void setTimes(int t){times=t;} public SVFrameRecipeInventory getDisplay(){return display;} }
